#define STACK_SIZE (1024 * 64)
char child_stack[STACK_SIZE];

int child_func(void *arg) {
    // Child execution context
    return 0;
}

// Prepare stack pointer (top of allocated memory)
void *stack_top = child_stack + STACK_SIZE;

// Flags: Share Virtual Memory (VM) and File System (FS)
int flags = CLONE_VM | CLONE_FILES | CLONE_FS;

// Execute clone
pid_t child_pid = clone(
    child_func,
    stack_top,
    flags,
    (void *)0xDEADBEEF // Argument for child_func
);
